#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using u32 = uint32_t;
using i128 = __int128_t;

constexpr int MAX_N = 22000002;
constexpr int M = 7;

static u32 prime_count[MAX_N];
static vector<bool> composite(MAX_N);
static vector<u32> primes;
static vector<u32> phi[M + 1];
static i64 period_size[M + 1];

static int integer_sqrt(i64 x) {
    i64 r = static_cast<i64>(sqrtl(static_cast<long double>(x)));
    while (static_cast<i128>(r + 1) * (r + 1) <= x) ++r;
    while (static_cast<i128>(r) * r > x) --r;
    return static_cast<int>(r);
}

static int integer_cbrt(i64 x) {
    i64 r = static_cast<i64>(cbrtl(static_cast<long double>(x)));
    while (static_cast<i128>(r + 1) * (r + 1) * (r + 1) <= x) ++r;
    while (static_cast<i128>(r) * r * r > x) --r;
    return static_cast<int>(r);
}

static void build_sieve() {
    primes.reserve(1500000);
    primes.push_back(0);

    composite[0] = composite[1] = true;

    for (int i = 2; i < MAX_N; ++i) {
        if (!composite[i]) primes.push_back(static_cast<u32>(i));

        prime_count[i] = static_cast<u32>(primes.size() - 1);

        for (size_t j = 1; j < primes.size(); ++j) {
            i64 value = static_cast<i64>(i) * primes[j];
            if (value >= MAX_N) break;

            composite[static_cast<size_t>(value)] = true;
            if (i % primes[j] == 0) break;
        }
    }

    composite.clear();
    composite.shrink_to_fit();
}

static void build_phi_table() {
    period_size[0] = 1;
    phi[0] = {0, 1};

    for (int s = 1; s <= M; ++s) {
        const i64 previous_period = period_size[s - 1];
        period_size[s] = previous_period * primes[s];

        phi[s].resize(static_cast<size_t>(period_size[s]) + 1);

        const u32 previous_total = phi[s - 1][previous_period];

        auto previous_phi = [&](i64 x) -> i64 {
            return (x / previous_period) * previous_total
                 + phi[s - 1][x % previous_period];
        };

        for (i64 x = 0; x <= period_size[s]; ++x) {
            phi[s][x] = static_cast<u32>(
                previous_phi(x) - previous_phi(x / primes[s])
            );
        }
    }
}

static void init() {
    build_sieve();
    build_phi_table();
}

static i64 get_phi(i64 x, int s) {
    if (s == 0) return x;

    if (s <= M) {
        const i64 period = period_size[s];
        return phi[s][x % period]
             + (x / period) * static_cast<i64>(phi[s][period]);
    }

    const i64 p = primes[s];

    if (static_cast<i128>(p) * p >= x) {
        return static_cast<i64>(prime_count[x]) - s + 1;
    }

    if (x < MAX_N && static_cast<i128>(p) * p * p >= x) {
        const int root_count = prime_count[integer_sqrt(x)];
        i64 answer = static_cast<i64>(prime_count[x])
                   - static_cast<i64>(root_count + s - 2)
                   * (root_count - s + 1) / 2;

        for (int i = s + 1; i <= root_count; ++i) {
            answer += prime_count[x / primes[i]];
        }
        return answer;
    }

    return get_phi(x, s - 1) - get_phi(x / primes[s], s - 1);
}

static i64 lehmer_pi(i64 x) {
    if (x < MAX_N) return prime_count[x];

    const int a = static_cast<int>(lehmer_pi(integer_sqrt(integer_sqrt(x))));
    const int b = static_cast<int>(lehmer_pi(integer_sqrt(x)));
    const int c = static_cast<int>(lehmer_pi(integer_cbrt(x)));

    i64 sum = get_phi(x, a)
            + static_cast<i64>(b + a - 2) * (b - a + 1) / 2;

    for (int i = a + 1; i <= b; ++i) {
        const i64 w = x / primes[i];
        sum -= lehmer_pi(w);

        if (i <= c) {
            const int limit = static_cast<int>(lehmer_pi(integer_sqrt(w)));
            for (int j = i; j <= limit; ++j) {
                sum -= lehmer_pi(w / primes[j]) - (j - 1);
            }
        }
    }

    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 n;
    cin >> n;

    init();

    i64 answer = 0;
    const int root = integer_sqrt(n);

    for (int i = 1; i < static_cast<int>(primes.size()) && primes[i] <= root; ++i) {
        const i64 p = primes[i];
        answer += lehmer_pi(n / p) - lehmer_pi(p);
    }

    answer += max<i64>(0, static_cast<i64>(integer_cbrt(n)) - 1);

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

constexpr int MAX_N = 22000002;
constexpr int M = 8;

vector<int> primes;
vector<uint64_t> prime_bits;
vector<uint32_t> prime_rank;

array<vector<uint32_t>, M + 1> phi_table;
array<int, M + 1> period_size;

inline bool is_prime(int x) {
    return x >= 2 && ((prime_bits[x >> 6] >> (x & 63)) & 1ULL);
}

inline int prime_pi(ll x) {
    if (x < 2) return 0;

    int value = static_cast<int>(x);
    int word = value >> 6;
    int bit = value & 63;

    uint64_t mask = (bit == 63)
        ? ~0ULL
        : ((1ULL << (bit + 1)) - 1);

    return static_cast<int>(
        prime_rank[word] + __builtin_popcountll(prime_bits[word] & mask)
    );
}

void build_primes() {
    vector<bool> composite(MAX_N, false);
    composite[0] = composite[1] = true;

    for (int i = 2; 1LL * i * i < MAX_N; ++i) {
        if (!composite[i]) {
            for (ll j = 1LL * i * i; j < MAX_N; j += i)
                composite[static_cast<int>(j)] = true;
        }
    }

    primes.reserve(1500000);
    primes.push_back(0);

    int words = (MAX_N + 63) >> 6;
    prime_bits.assign(words, 0);

    for (int i = 2; i < MAX_N; ++i) {
        if (!composite[i]) {
            primes.push_back(i);
            prime_bits[i >> 6] |= 1ULL << (i & 63);
        }
    }

    prime_rank.resize(words + 1);
    for (int i = 0; i < words; ++i) {
        prime_rank[i + 1] =
            prime_rank[i] + __builtin_popcountll(prime_bits[i]);
    }

    vector<bool>().swap(composite);
}

inline ll periodic_phi(ll x, int s) {
    int period = period_size[s];
    return (x / period) * phi_table[s][period]
         + phi_table[s][x % period];
}

void init() {
    build_primes();

    period_size[0] = 1;
    phi_table[0] = {0, 1};

    for (int s = 1; s <= M; ++s) {
        int p = primes[s];
        int previous_period = period_size[s - 1];
        period_size[s] = previous_period * p;

        phi_table[s].resize(period_size[s] + 1);

        for (int x = 0; x <= period_size[s]; ++x) {
            ll first = periodic_phi(x, s - 1);
            ll second = periodic_phi(x / p, s - 1);
            phi_table[s][x] = static_cast<uint32_t>(first - second);
        }
    }
}

