    ll result = static_cast<ll>(sqrtl(static_cast<long double>(x)));

    while ((__int128)(result + 1) * (result + 1) <= x)
        ++result;
    while ((__int128)result * result > x)
        --result;

    return result;
}

ll integer_cbrt(ll x) {
    ll result = static_cast<ll>(cbrtl(static_cast<long double>(x)));

    while ((__int128)(result + 1) * (result + 1) * (result + 1) <= x)
        ++result;
    while ((__int128)result * result * result > x)
        --result;

    return result;
}

ll getphi(ll x, int s) {
