    if (s <= M)
        return periodic_phi(x, s);

    ll p = primes[s];

    if (x <= p * p)
        return prime_pi(x) - s + 1;

    if ((__int128)x <= (__int128)p * p * p && x < MAX_N) {
        int sqrt_count = prime_pi(integer_sqrt(x));
        ll answer = prime_pi(x)
                  - 1LL * (sqrt_count + s - 2)
                          * (sqrt_count - s + 1) / 2;

        for (int i = s + 1; i <= sqrt_count; ++i)
            answer += prime_pi(x / primes[i]);

        return answer;
    }

    return getphi(x, s - 1) - getphi(x / p, s - 1);
}

