    if (x < MAX_N)
        return prime_pi(x);

    ll cube_root = integer_cbrt(x);
    int cube_count = prime_pi(cube_root);

    ll answer = getphi(x, cube_count) + cube_count - 1;
    int end = prime_pi(integer_sqrt(x));

    for (int i = cube_count + 1; i <= end; ++i)
        answer -= getpi(x / primes[i]) - i + 1;

    return answer;
}

ll lehmer_pi(ll x) {
    if (x < MAX_N)
        return prime_pi(x);

    int a = static_cast<int>(lehmer_pi(integer_sqrt(integer_sqrt(x))));
    int b = static_cast<int>(lehmer_pi(integer_sqrt(x)));
    int c = static_cast<int>(lehmer_pi(integer_cbrt(x)));

    ll sum = getphi(x, a)
           + 1LL * (b + a - 2) * (b - a + 1) / 2;

    for (int i = a + 1; i <= b; ++i) {
        ll w = x / primes[i];
        sum -= lehmer_pi(w);

        if (i <= c) {
            int limit = static_cast<int>(lehmer_pi(integer_sqrt(w)));
            for (int j = i; j <= limit; ++j)
                sum -= lehmer_pi(w / primes[j]) - (j - 1);
        }
    }

    return sum;
}

