    ll n;
    cin >> n;

    init();

    ll answer = 0;

    for (ll i = 2; i * i <= n; ++i) {
        if (is_prime(static_cast<int>(i)))
            answer += lehmer_pi(n / i) - lehmer_pi(i);
    }

    for (ll i = 2; (__int128)i * i * i <= n; ++i)
        ++answer;

    cout << answer << '\n';
}

